"use client";

import React, { useState, useMemo, useRef, useEffect } from "react";
import { 
  Calendar as CalendarIcon, 
  ChevronDown, 
  CheckCircle2, 
  UploadCloud, 
  Clock, 
  Plane, 
  Stethoscope, 
  Briefcase, 
  Baby, 
  Umbrella, 
  GraduationCap, 
  Heart, 
  AlertOctagon, 
  X,
  Trash2
} from "lucide-react";

// --- CONFIGURATION ---
const HOLIDAYS = [
  { date: "2026-01-26", name: "Republic Day" }
];

const LEAVE_TYPES = [
  { id: "annual", label: "Annual Leave", icon: Plane, balance: 18, color: "text-blue-600", bg: "bg-blue-50" },
  { id: "sick", label: "Sick Leave", icon: Stethoscope, balance: 12, color: "text-rose-600", bg: "bg-rose-50", requiresDoc: true },
  { id: "casual", label: "Casual Leave", icon: Briefcase, balance: 6, color: "text-amber-600", bg: "bg-amber-50" },
  { id: "comp_off", label: "Compensatory Off", icon: Umbrella, balance: 3, color: "text-emerald-600", bg: "bg-emerald-50" },
  { id: "maternity", label: "Maternity", icon: Baby, balance: 90, color: "text-purple-600", bg: "bg-purple-50", requiresDoc: true },
  { id: "bereavement", label: "Bereavement", icon: Heart, balance: 5, color: "text-slate-600", bg: "bg-slate-100" },
  { id: "unpaid", label: "Loss of Pay", icon: AlertOctagon, balance: 0, color: "text-red-600", bg: "bg-red-50" },
];

export default function MultiSelectAbsence() {
  // --- STATE ---
  const [mode, setMode] = useState<"range" | "multi">("range");
  
  // State for Range Mode
  const [range, setRange] = useState<{ start: string; end: string }>({ start: "", end: "" });
  
  // State for Multi Mode (Array of strings)
  const [multiDates, setMultiDates] = useState<string[]>([]);

  const [typeId, setTypeId] = useState("annual");
  const [reason, setReason] = useState("");
  const [file, setFile] = useState<File | null>(null);
  const [isDropdownOpen, setIsDropdownOpen] = useState(false);
  
  const dropdownRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Close dropdown on click outside
  useEffect(() => {
    function handleClickOutside(event: MouseEvent) {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
        setIsDropdownOpen(false);
      }
    }
    document.addEventListener("mousedown", handleClickOutside);
    return () => document.removeEventListener("mousedown", handleClickOutside);
  }, []);

  // --- LOGIC: DATE HANDLING ---
  const handleDateClick = (dateStr: string) => {
    if (mode === "multi") {
      // Toggle logic for multi-select
      setMultiDates(prev => {
        if (prev.includes(dateStr)) {
          return prev.filter(d => d !== dateStr); // Remove if exists
        } else {
          return [...prev, dateStr].sort(); // Add and sort
        }
      });
    } else {
      // Logic for Range
      if (!range.start || (range.start && range.end)) {
        setRange({ start: dateStr, end: "" });
      } else {
        const s = new Date(range.start);
        const e = new Date(dateStr);
        if (e < s) setRange({ start: dateStr, end: "" });
        else setRange({ ...range, end: dateStr });
      }
    }
  };

  // --- LOGIC: STATS CALCULATOR ---
  const stats = useMemo(() => {
    let days = 0;
    let deduction = 0;

    // Helper to check validity
    const checkDay = (dStr: string) => {
      const dObj = new Date(dStr);
      const isHoliday = HOLIDAYS.some(h => h.date === dStr);
      const isWeekend = dObj.getDay() === 0 || dObj.getDay() === 6;
      if (!isHoliday && !isWeekend) return 1;
      return 0;
    };

    if (mode === "multi") {
      days = multiDates.length;
      deduction = multiDates.reduce((acc, date) => acc + checkDay(date), 0);
    } else {
      if (!range.start || !range.end) return { days: 0, deduction: 0 };
      let cur = new Date(range.start);
      let end = new Date(range.end);
      while (cur <= end) {
        deduction += checkDay(cur.toISOString().split('T')[0]);
        days++;
        cur.setDate(cur.getDate() + 1);
      }
    }

    return { days, deduction };
  }, [range, multiDates, mode]);

  const selectedType = LEAVE_TYPES.find(t => t.id === typeId)!;
  const hasSelection = mode === "multi" ? multiDates.length > 0 : (range.start && range.end);

  return (
    <div className="flex h-screen w-full bg-[#F8FAFC] dark:bg-black font-sans text-slate-800 dark:text-slate-100 overflow-hidden transition-colors duration-200">
      
      {/* --- LEFT: CALENDAR (65%) --- */}
      <div className="flex-1 flex flex-col p-6 pr-0 gap-6 h-full">
        
        {/* Header */}
        <div className="flex items-center justify-between shrink-0">
           <div>
              <h1 className="text-2xl font-bold text-slate-900 dark:text-white flex items-center gap-2">
                <CalendarIcon className="h-6 w-6 text-blue-600" /> 
                Absence Portal
              </h1>
              <p className="text-xs font-medium text-slate-500 dark:text-slate-400">Manage time off requests</p>
           </div>
           
           {/* MODE SWITCHER */}
           <div className="bg-white dark:bg-slate-900 p-1 rounded-xl shadow-sm border border-slate-200 dark:border-slate-800 flex">
              <button 
                onClick={() => { setMode("range"); setMultiDates([]); }}
                className={`px-5 py-2 rounded-lg text-xs font-bold transition-all ${
                  mode === "range" 
                  ? "bg-slate-900 dark:bg-blue-600 text-white shadow" 
                  : "text-slate-500 dark:text-slate-400 hover:bg-slate-50 dark:hover:bg-slate-800"
                }`}
              >
                Date Range
              </button>
              <button 
                onClick={() => { setMode("multi"); setRange({start:"", end:""}); }}
                className={`px-5 py-2 rounded-lg text-xs font-bold transition-all ${
                  mode === "multi" 
                  ? "bg-slate-900 dark:bg-blue-600 text-white shadow" 
                  : "text-slate-500 dark:text-slate-400 hover:bg-slate-50 dark:hover:bg-slate-800"
                }`}
              >
                Select Multiple Days
              </button>
           </div>
        </div>

        {/* Calendar Canvas */}
        <div className="flex-1 bg-white dark:bg-slate-900 rounded-3xl border border-slate-200 dark:border-slate-800 shadow-sm flex flex-col overflow-hidden relative">
           
           {/* Calendar Top Bar */}
           <div className="flex items-center justify-between px-8 py-6 border-b border-slate-100 dark:border-slate-800 shrink-0">
              <h2 className="text-xl font-bold text-slate-800 dark:text-white">January 2026</h2>
              
              {/* Reset Button */}
              {hasSelection && (
                <button 
                  onClick={() => { setMultiDates([]); setRange({start:"", end:""}); }}
                  className="flex items-center gap-1 text-xs font-bold text-rose-500 hover:bg-rose-50 dark:hover:bg-rose-900/20 px-3 py-1.5 rounded-lg transition-colors"
                >
                  <Trash2 className="h-3 w-3" /> Clear Selection
                </button>
              )}
           </div>

           {/* The Grid */}
           <div className="flex-1 p-8 overflow-y-auto">
              <div className="grid grid-cols-7 gap-3 h-full content-start">
                 {['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'].map(d => (
                    <div key={d} className="text-center text-[10px] font-black text-slate-300 dark:text-slate-600 uppercase mb-2">{d}</div>
                 ))}
                 
                 {[null, null, null].map((_, i) => <div key={`e-${i}`}/>)}

                 {Array.from({ length: 31 }).map((_, i) => {
                    const day = i + 1;
                    const dateStr = `2026-01-${day < 10 ? `0${day}` : day}`;
                    const holiday = HOLIDAYS.find(h => h.date === dateStr);
                    const isWeekend = new Date(2026, 0, day).getDay() % 6 === 0;

                    // Determination Logic
                    let isSelected = false;
                    let inRange = false;

                    if (mode === "range") {
                        isSelected = range.start === dateStr || range.end === dateStr;
                        inRange = range.start && range.end && dateStr > range.start && dateStr < range.end;
                    } else {
                        isSelected = multiDates.includes(dateStr);
                    }

                    return (
                       <button
                         key={day}
                         onClick={() => handleDateClick(dateStr)}
                         className={`
                           relative h-20 rounded-2xl border text-left p-3 transition-all group
                           ${isSelected 
                              ? "bg-slate-900 dark:bg-blue-600 text-white border-slate-900 dark:border-blue-600 shadow-xl scale-105 z-10" 
                              : ""}
                           ${inRange 
                              ? "bg-blue-50 dark:bg-blue-900/20 text-blue-700 dark:text-blue-100 border-blue-100 dark:border-blue-800" 
                              : ""}
                           ${!isSelected && !inRange && holiday 
                              ? "bg-rose-50 dark:bg-rose-900/20 border-rose-100 dark:border-rose-900/50" 
                              : ""}
                           ${!isSelected && !inRange && isWeekend 
                              ? "bg-slate-50 dark:bg-slate-800/50 border-transparent text-slate-300 dark:text-slate-600" 
                              : "bg-white dark:bg-slate-900 border-slate-100 dark:border-slate-800 hover:border-blue-400 dark:hover:border-blue-500"}
                         `}
                       >
                          <span className="text-sm font-bold">{day}</span>
                          {holiday && <span className={`absolute bottom-2 left-2 text-[9px] font-bold px-1.5 py-0.5 rounded ${isSelected ? "bg-white/20 text-white" : "bg-rose-100 dark:bg-rose-900/40 text-rose-600 dark:text-rose-300"}`}>{holiday.name}</span>}
                          
                          {/* Indicator dot for Multi-Select */}
                          {mode === "multi" && isSelected && (
                             <span className="absolute top-3 right-3 h-2 w-2 rounded-full bg-white animate-in zoom-in"></span>
                          )}
                       </button>
                    )
                 })}
              </div>
           </div>
        </div>
      </div>

      {/* --- RIGHT: CONTROL PANEL (35% / Fixed width) --- */}
      <div className="w-[420px] flex-none p-6 flex flex-col gap-6 h-full">
         
         {/* 1. Request Form Card */}
         <div className="flex-1 bg-white dark:bg-slate-900 rounded-3xl border border-slate-200 dark:border-slate-800 shadow-sm flex flex-col overflow-hidden">
            
            <div className="p-6 border-b border-slate-100 dark:border-slate-800 bg-slate-50/50 dark:bg-slate-950/30 shrink-0">
               <h3 className="text-xs font-bold uppercase tracking-widest text-slate-400 dark:text-slate-500 mb-4">Request Configuration</h3>
               
               {/* CUSTOM DROPDOWN */}
               <div className="relative" ref={dropdownRef}>
                  <button 
                    onClick={() => setIsDropdownOpen(!isDropdownOpen)}
                    className="w-full flex items-center justify-between bg-white dark:bg-slate-950 border border-slate-200 dark:border-slate-700 rounded-xl p-4 transition-all hover:border-blue-400"
                  >
                     <div className="flex items-center gap-3">
                        <div className={`p-1.5 rounded-md ${selectedType.bg} ${selectedType.color}`}>
                           <selectedType.icon className="h-4 w-4" />
                        </div>
                        <div className="text-left">
                           <p className="text-sm font-bold text-slate-900 dark:text-white">{selectedType.label}</p>
                        </div>
                     </div>
                     <div className="flex items-center gap-3">
                        <span className="text-[10px] font-bold bg-slate-100 dark:bg-slate-800 px-2 py-1 rounded text-slate-600 dark:text-slate-300">
                           Bal: {selectedType.balance}
                        </span>
                        <ChevronDown className={`h-4 w-4 text-slate-400 transition-transform ${isDropdownOpen ? 'rotate-180' : ''}`} />
                     </div>
                  </button>

                  {/* Dropdown Menu */}
                  {isDropdownOpen && (
                     <div className="absolute top-full left-0 right-0 mt-2 bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-700 rounded-xl shadow-xl z-50 max-h-[300px] overflow-y-auto custom-scrollbar p-1">
                        {LEAVE_TYPES.map(t => (
                           <button
                             key={t.id}
                             onClick={() => { setTypeId(t.id); setIsDropdownOpen(false); }}
                             className="w-full flex items-center justify-between p-3 hover:bg-slate-50 dark:hover:bg-slate-800 rounded-lg group"
                           >
                              <div className="flex items-center gap-3">
                                 <div className={`p-1.5 rounded-md ${t.bg} ${t.color}`}>
                                    <t.icon className="h-4 w-4" />
                                 </div>
                                 <span className="text-sm font-medium text-slate-700 dark:text-slate-300 group-hover:text-slate-900 dark:group-hover:text-white">{t.label}</span>
                              </div>
                              <span className="text-[10px] font-bold text-slate-400">{t.balance} left</span>
                           </button>
                        ))}
                     </div>
                  )}
               </div>
            </div>

            <div className="flex-1 p-6 space-y-6 overflow-y-auto">
               
               {/* Summary Stats */}
               <div className="bg-slate-50 dark:bg-slate-800/50 rounded-xl p-4 border border-slate-100 dark:border-slate-700 space-y-3">
                  <div className="flex justify-between items-center">
                     <span className="text-xs text-slate-500 dark:text-slate-400 font-bold uppercase">Selection Type</span>
                     <span className="text-xs font-bold text-slate-900 dark:text-white capitalize">{mode} Selection</span>
                  </div>
                  
                  {/* List of Selected Dates (Improvised Feature) */}
                  {mode === "multi" && multiDates.length > 0 && (
                     <div className="flex flex-wrap gap-1.5">
                        {multiDates.map(d => (
                           <span key={d} className="text-[10px] font-bold bg-white dark:bg-slate-700 border border-slate-200 dark:border-slate-600 px-2 py-1 rounded text-slate-600 dark:text-slate-300">
                              Jan {d.split('-')[2]}
                           </span>
                        ))}
                     </div>
                  )}

                  {mode === "range" && range.start && (
                     <div className="text-xs font-bold text-slate-900 dark:text-white bg-white dark:bg-slate-700 p-2 rounded border border-slate-200 dark:border-slate-600 text-center">
                        {range.start} <span className="text-slate-400 mx-2">to</span> {range.end || "..."}
                     </div>
                  )}

                  <div className="h-px bg-slate-200 dark:bg-slate-700 my-1"/>
                  
                  <div className="flex justify-between items-center">
                     <span className="text-xs font-bold text-slate-700 dark:text-slate-300">Net Deduction</span>
                     <span className="text-xl font-black text-slate-900 dark:text-white">{stats.deduction} Days</span>
                  </div>
               </div>

               {/* Reason */}
               <div>
                  <label className="text-[10px] font-bold uppercase text-slate-400 dark:text-slate-500 mb-2 block">Reason for Absence</label>
                  <textarea 
                     className="w-full h-24 rounded-xl border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-950 p-3 text-xs font-medium text-slate-900 dark:text-white focus:ring-2 focus:ring-slate-900 dark:focus:ring-blue-500 outline-none resize-none"
                     placeholder="Enter details..."
                     value={reason}
                     onChange={(e) => setReason(e.target.value)}
                  />
               </div>

               {/* Attachment (Conditional) */}
               {selectedType.requiresDoc && (
                  <div className="animate-in zoom-in-95">
                     <label className="text-[10px] font-bold uppercase text-slate-400 dark:text-slate-500 mb-2 block flex justify-between">
                        <span>Attachment</span> <span className="text-rose-500 dark:text-rose-400">* Required</span>
                     </label>
                     <div 
                        onClick={() => fileInputRef.current?.click()}
                        className={`border-2 border-dashed rounded-xl h-16 flex items-center justify-center cursor-pointer transition-colors gap-2 ${
                           file 
                           ? "border-emerald-500 bg-emerald-50 dark:bg-emerald-900/20" 
                           : "border-slate-200 dark:border-slate-700 hover:border-blue-400 dark:hover:border-blue-500 hover:bg-slate-50 dark:hover:bg-slate-800"
                        }`}
                     >
                        <input type="file" className="hidden" ref={fileInputRef} onChange={(e) => e.target.files && setFile(e.target.files[0])} />
                        {file ? (
                           <span className="text-xs font-bold text-emerald-600 dark:text-emerald-400 flex items-center gap-1"><CheckCircle2 className="h-4 w-4"/> {file.name}</span>
                        ) : (
                           <>
                             <UploadCloud className="h-4 w-4 text-slate-400" />
                             <span className="text-[10px] font-bold text-slate-500 dark:text-slate-400">Upload Proof</span>
                           </>
                        )}
                     </div>
                  </div>
               )}
            </div>
            
            {/* Submit Section */}
            <div className="p-6 border-t border-slate-100 dark:border-slate-800 bg-slate-50 dark:bg-slate-950/30 shrink-0">
               <button 
                  disabled={!hasSelection || (selectedType.requiresDoc && !file)}
                  className="w-full bg-slate-900 dark:bg-blue-600 text-white py-4 rounded-xl font-bold text-sm shadow-lg hover:bg-black dark:hover:bg-blue-500 disabled:bg-slate-300 dark:disabled:bg-slate-800 dark:disabled:text-slate-500 transition-all mb-4"
               >
                  {mode === "multi" 
                    ? `Request ${stats.deduction} Days` 
                    : "Submit Request"}
               </button>
               
               <div className="flex items-center justify-center gap-2 opacity-60">
                  <Clock className="h-3 w-3 text-slate-500 dark:text-slate-400" />
                  <span className="text-[10px] font-medium text-slate-500 dark:text-slate-400">Avg Approval: 4 Hours</span>
               </div>
            </div>
         </div>

      </div>
    </div>
  );
}